mapper.select:
select count(1) from prompt_template
and state = #{state}
and ( template_code like concat('%', #{keyword}, '%') or template_name like concat('%', #{keyword}, '%') )

select id, template_code, template_name, version_no, state, content, variable_spec_json, created_by, updated_by, created_at, updated_at from prompt_template
and state = #{state}
and ( template_code like concat('%', #{keyword}, '%') or template_name like concat('%', #{keyword}, '%') )
order by updated_at desc, id desc limit #{pageSize} offset #{offset}

select count(1)
from prompt_template
where template_code = #{templateCode}
